import React, {useEffect, useState} from 'react'
import axios from "axios";
import './App.css';
import {BrowserRouter as Router, Switch, Route, Redirect} from "react-router-dom";
import professorList from './json/professorsList.json'
//Pages
import Home from './pages/Home.js'
import NotFoundPage from './pages/404'
import Professor from "./pages/Professor";
//hooks
import useProfessor from "./hooks/useProfessor";
import {ApiProfessor} from "./api";


function App() {

  let [professor, isLoadingProfessor, setProfessor] = useProfessor();


  return (
      <Router>
        <Switch>
          <Route path='/' exact component={() => <Home professorList={professorList} onChangeProfessor={setProfessor} isHome={true}/>}/>

            {!isLoadingProfessor && <Route path="/professors/:endpoint" exact component={() => <Professor isHome={false} endpoint={professor.endpoint} professorList={professorList} onChangeProfessor={setProfessor} professor={professor} />} />}

        </Switch>
      </Router>
  );
}

export default App;
